erializeQueryArgs : exclude value\"\n   * import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\n   *\n   * interface Post {\n   *   id: number;\n   *   name: string;\n   * }\n   *\n   * interface MyApiClient {\n   *   fetchPost: (id: string) => Promise<Post>;\n   * }\n   *\n   * createApi({\n   *   baseQuery: fetchBaseQuery({ baseUrl: '/' }),\n   *   endpoints: (build) => ({\n   *     // Example: an endpoint with an API client passed in as an argument,\n   *     // but only the item ID should be used as the cache key\n   *     getPost: build.query<Post, { id: string; client: MyApiClient }>({\n   *       queryFn: async ({ id, client }) => {\n   *         const post = await client.fetchPost(id);\n   *         return { data: post };\n   *       },\n   *       // highlight-start\n   *       serializeQueryArgs: ({ queryArgs, endpointDefinition, endpointName }) => {\n   *         const { id } = queryArgs;\n   *         // This can return a string, an object, a number, or a boolean.\n   *         // If it returns an object, number or boolean, that value\n   *         // will be serialized automatically via `defaultSerializeQueryArgs`\n   *         return { id }; // omit `client` from the cache key\n   *\n   *         // Alternately, you can use `defaultSerializeQueryArgs` yourself:\n   *         // return defaultSerializeQueryArgs({\n   *         //   endpointName,\n   *         //   queryArgs: { id },\n   *         //   endpointDefinition\n   *         // })\n   *         // Or  create and return a string yourself:\n   *         // return `getPost(${id})`\n   *       },\n   *       // highlight-end\n   *     }),\n   *   }),\n   * });\n   * ```\n   */\n  serializeQueryArgs?: SerializeQueryArgs<\n    QueryArg,\n    string | number | boolean | Record<any, any>\n  >\n\n  /**\n   * All of these are `undefined` at runtime, purely to be used in TypeScript declarations!\n   */\n  Types?: InfiniteQueryTypes<\n    QueryArg,\n    PageParam,\n    BaseQuery,\n    TagTypes,\n    ResultType,\n    ReducerPath,\n    RawResultType\n  >\n}\n\nexport type InfiniteQueryDefinition<\n  QueryArg,\n  PageParam,\n  BaseQuery extends BaseQueryFn,\n  TagTypes extends string,\n  ResultType,\n  ReducerPath extends string = string,\n  RawResultType extends BaseQueryResult<BaseQuery> = BaseQueryResult<BaseQuery>,\n> =\n  // Infinite query endpoints receive `{queryArg, pageParam}`\n  BaseEndpointDefinition<\n    InfiniteQueryCombinedArg<QueryArg, PageParam>,\n    BaseQuery,\n    ResultType,\n    RawResultType\n  > &\n    InfiniteQueryExtraOptions<\n      TagTypes,\n      ResultType,\n      QueryArg,\n      PageParam,\n      BaseQuery,\n      ReducerPath,\n      RawResultType\n    >\n\ntype MutationTypes<\n  QueryArg,\n  BaseQuery extends BaseQueryFn,\n  TagTypes extends string,\n  ResultType,\n  ReducerPath extends string = string,\n  RawResultType extends BaseQueryResult<BaseQuery> = BaseQueryResult<BaseQuery>,\n> = BaseEndpointTypes<QueryArg, BaseQuery, ResultType, RawResultType> & {\n  /**\n   * The endpoint definition type. To be used with some internal generic types.\n   * @example\n   * ```ts\n   * const useMyWrappedHook: UseMutation<typeof api.endpoints.query.Types.MutationDefinition> = ...\n   * ```\n   */\n  MutationDefinition: MutationDefinition<\n    QueryArg,\n    BaseQuery,\n    TagTypes,\n    ResultType,\n    ReducerPath\n  >\n  TagTypes: TagTypes\n  ReducerPath: ReducerPath\n}\n\n/**\n * @public\n */\nexport interface MutationExtraOptions<\n  TagTypes extends string,\n  ResultType,\n  QueryArg,\n  BaseQuery extends BaseQueryFn,\n  ReducerPath extends string = string,\n  RawResultType extends BaseQueryResult<BaseQuery> = BaseQueryResult<BaseQuery>,\n>\n  extends\n    CacheLifecycleMutationExtraOptions<\n      ResultType,\n      QueryArg,\n      BaseQuery,\n      ReducerPath\n    >,\n    QueryLifecycleMutationExtraOptions<\n      ResultType,\n      QueryArg,\n      BaseQuery,\n      ReducerPath\n    > {\n  type: DefinitionType.mutation\n\n  /**\n   * Used by `mutation` endpoints. Determines which cached data should be either re-fetched or removed from the cache.\n   * Expects the same shapes as `providesTags`.\n   *\n   * @example\n   *\n   * ```ts\n   * // codeblock-meta title=\"invalidatesTags example\"\n   * import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\n   *\n   * interface Post {\n   *   id: number;\n   *   name: string;\n   * }\n   *\n   * type PostsResponse = Post[];\n   *\n   * const api = createApi({\n   *   baseQuery: fetchBaseQuery({ baseUrl: '/' }),\n   *   tagTypes: ['Posts'],\n   *   endpoints: (build) => ({\n   *     getPosts: build.query<PostsResponse, void>({\n   *       query: () => 'posts',\n   *       providesTags: (result) =>\n   *         result\n   *           ? [\n   *               ...result.map(({ id }) => ({ type: 'Posts' as const, id })),\n   *               { type: 'Posts', id: 'LIST' },\n   *             ]\n   *           : [{ type: 'Posts', id: 'LIST' }],\n   *     }),\n   *     addPost: build.mutation<Post, Partial<Post>>({\n   *       query(body) {\n   *         return {\n   *           url: `posts`,\n   *           method: 'POST',\n   *           body,\n   *         };\n   *       },\n   *       // highlight-start\n   *       invalidatesTags: [{ type: 'Posts', id: 'LIST' }],\n   *       // highlight-end\n   *     }),\n   *   }),\n   * });\n   * ```\n   */\n  invalidatesTags?: ResultDescription<\n    TagTypes,\n    ResultType,\n    QueryArg,\n    BaseQueryError<BaseQuery>,\n    BaseQueryMeta<BaseQuery>\n  >\n  /**\n   * Not to be used. A mutation should not provide tags to the cache.\n   */\n  providesTags?: never\n\n  /**\n   * All of these are `undefined` at runtime, purely to be used in TypeScript declarations!\n   */\n  Types?: MutationTypes<\n    QueryArg,\n    BaseQuery,\n    TagTypes,\n    ResultType,\n    ReducerPath,\n    RawResultType\n  >\n}\n\nexport type MutationDefinition<\n  QueryArg,\n  BaseQuery extends BaseQueryFn,\n  TagTypes extends string,\n  ResultType,\n  ReducerPath extends string = string,\n  RawResultType extends BaseQueryResult<BaseQuery> = BaseQueryResult<BaseQuery>,\n> = BaseEndpointDefinition<QueryArg, BaseQuery, ResultType, RawResultType> &\n  MutationExtraOptions<\n    TagTypes,\n    ResultType,\n    QueryArg,\n    BaseQuery,\n    ReducerPath,\n    RawResultType\n  >\n\nexport type EndpointDefinition<\n  QueryArg,\n  BaseQuery extends BaseQueryFn,\n  TagTypes extends string,\n  ResultType,\n  ReducerPath extends string = string,\n  PageParam = any,\n  RawResultType extends BaseQueryResult<BaseQuery> = BaseQueryResult<BaseQuery>,\n> =\n  | QueryDefinition<\n      QueryArg,\n      BaseQuery,\n      TagTypes,\n      ResultType,\n      ReducerPath,\n      RawResultType\n    >\n  | MutationDefinition<\n      QueryArg,\n      BaseQuery,\n      TagTypes,\n      ResultType,\n      ReducerPath,\n      RawResultType\n    >\n  | InfiniteQueryDefinition<\n      QueryArg,\n      PageParam,\n      BaseQuery,\n      TagTypes,\n      ResultType,\n      ReducerPath,\n      RawResultType\n    >\n\nexport type EndpointDefinitions = Record<\n  string,\n  EndpointDefinition<any, any, any, any, any, any, any>\n>\n\nexport function isQueryDefinition(\n  e: EndpointDefinition<any, any, any, any, any, any, any>,\n): e is QueryDefinition<any, any, any, any, any, any> {\n  return e.type === ENDPOINT_QUERY\n}\n\nexport function isMutationDefinition(\n  e: EndpointDefinition<any, any, any, any, any, any, any>,\n): e is MutationDefinition<any, any, any, any, any, any> {\n  return e.type === ENDPOINT_MUTATION\n}\n\nexport function isInfiniteQueryDefinition(\n  e: EndpointDefinition<any, any, any, any, any, any, any>,\n): e is InfiniteQueryDefinition<any, any, any, any, any, any, any> {\n  return e.type === ENDPOINT_INFINITEQUERY\n}\n\nexport function isAnyQueryDefinition(\n  e: EndpointDefinition<any, any, any, any>,\n): e is\n  | QueryDefinition<any, any, any, any>\n  | InfiniteQueryDefinition<any, any, any, any, any> {\n  return isQueryDefinition(e) || isInfiniteQueryDefinition(e)\n}\n\nexport type EndpointBuilder<\n  BaseQuery extends BaseQueryFn,\n  TagTypes extends string,\n  ReducerPath extends string,\n> = {\n  /**\n   * An endpoint definition that retrieves data, and may provide tags to the cache.\n   *\n   * @example\n   * ```ts\n   * // codeblock-meta title=\"Example of all query endpoint options\"\n   * import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\n   *\n   * interface Post {\n   *   id: number;\n   *   name: string;\n   * }\n   *\n   * interface PostsResponse {\n   *   data: Post[];\n   * }\n   *\n   * const api = createApi({\n   *   baseQuery: fetchBaseQuery({ baseUrl: '/' }),\n   *   tagTypes: ['Post'],\n   *   endpoints: (build) => ({\n   *     getPost: build.query<Post[], number, PostsResponse>({\n   *       query: (id) => ({ url: `post/${id}` }),\n   *       // Pick out data and prevent nested properties in a hook or selector\n   *       transformResponse: (response) => response.data,\n   *       // Pick out error and prevent nested properties in a hook or selector\n   *       transformErrorResponse: (response) => response.status,\n   *       // `result` is the server response\n   *       providesTags: (result, error, id) => [{ type: 'Post', id }],\n   *       // trigger side effects or optimistic updates\n   *       onQueryStarted(\n   *         id,\n   *         {\n   *           dispatch,\n   *           getState,\n   *           extra,\n   *           requestId,\n   *           queryFulfilled,\n   *           getCacheEntry,\n   *           updateCachedData,\n   *         },\n   *       ) {},\n   *       // handle subscriptions etc\n   *       onCacheEntryAdded(\n   *         id,\n   *         {\n   *           dispatch,\n   *           getState,\n   *           extra,\n   *           requestId,\n   *           cacheEntryRemoved,\n   *           cacheDataLoaded,\n   *           getCacheEntry,\n   *           updateCachedData,\n   *         },\n   *       ) {},\n   *     }),\n   *   }),\n   * });\n   * ```\n   */\n  query<\n    ResultType,\n    QueryArg,\n    RawResultType extends BaseQueryResult<BaseQuery> =\n      BaseQueryResult<BaseQuery>,\n  >(\n    definition: OmitFromUnion<\n      QueryDefinition<\n        QueryArg,\n        BaseQuery,\n        TagTypes,\n        ResultType,\n        ReducerPath,\n        RawResultType\n      >,\n      'type'\n    >,\n  ): QueryDefinition<\n    QueryArg,\n    BaseQuery,\n    TagTypes,\n    ResultType,\n    ReducerPath,\n    RawResultType\n  >\n\n  /**\n   * An endpoint definition that alters data on the server or will possibly invalidate the cache.\n   *\n   * @example\n   * ```ts\n   * // codeblock-meta title=\"Example of all mutation endpoint options\"\n   * import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';\n   *\n   * interface Post {\n   *   id: number;\n   *   name: string;\n   * }\n   *\n   * interface PostsResponse {\n   *   data: Post[];\n   * }\n   *\n   * const api = createApi({\n   *   baseQuery: fetchBaseQuery({ baseUrl: '/' }),\n   *   tagTypes: ['Post'],\n   *   endpoints: (build) => ({\n   *     updatePost: build.mutation<Post[], Partial<Post>, PostsResponse>({\n   *       query: ({ id, ...patch }) => ({\n   *         url: `post/${id}`,\n   *         method: 'PATCH',\n   *         body: patch,\n   *       }),\n   *       // Pick out data and prevent nested properties in a hook or selector\n   *       transformResponse: (response) => response.data,\n   *       // Pick out error and prevent nested properties in a hook or selector\n   *       transformErrorResponse: (response) => response.status,\n   *       // `result` is the server response\n   *       invalidatesTags: (result, error, { id }) => [{ type: 'Post', id }],\n   *       // trigger side effects or optimistic updates\n   *       onQueryStarted(\n   *         { id },\n   *         { dispatch, getState, extra, requestId, queryFulfilled, getCacheEntry },\n   *       ) {},\n   *       // handle subscriptions etc\n   *       onCacheEntryAdded(\n   *         { id },\n   *         {\n   *           dispatch,\n   *           getState,\n   *           extra,\n   *           requestId,\n   *           cacheEntryRemoved,\n   *           cacheDataLoaded,\n   *           getCacheEntry,\n   *         },\n   *       ) {},\n   *     }),\n   *   }),\n   * });\n   * ```\n   */\n  mutation<\n    ResultType,\n    QueryArg,\n    RawResultType extends BaseQueryResult<BaseQuery> =\n      BaseQueryResult<BaseQuery>,\n  >(\n    definition: OmitFromUnion<\n      MutationDefinition<\n        QueryArg,\n        BaseQuery,\n        TagTypes,\n        ResultType,\n        ReducerPath,\n        RawResultType\n      >,\n      'type'\n    >,\n  ): MutationDefinition<\n    QueryArg,\n    BaseQuery,\n    TagTypes,\n    ResultType,\n    ReducerPath,\n    RawResultType\n  >\n\n  infiniteQuery<\n    ResultType,\n    QueryArg,\n    PageParam,\n    RawResultType extends BaseQueryResult<BaseQuery> =\n      BaseQueryResult<BaseQuery>,\n  >(\n    definition: OmitFromUnion<\n      InfiniteQueryDefinition<\n        QueryArg,\n        PageParam,\n        BaseQuery,\n        TagTypes,\n        ResultType,\n        ReducerPath,\n        RawResultType\n      >,\n      'type'\n    >,\n  ): InfiniteQueryDefinition<\n    QueryArg,\n    PageParam,\n    BaseQuery,\n    TagTypes,\n    ResultType,\n    ReducerPath,\n    RawResultType\n  >\n}\n\nexport type AssertTagTypes = <T extends FullTagDescription<string>>(t: T) => T\n\nexport function calculateProvidedBy<ResultType, QueryArg, ErrorType, MetaType>(\n  description:\n    | ResultDescription<string, ResultType, QueryArg, ErrorType, MetaType>\n    | undefined,\n  result: ResultType | undefined,\n  error: ErrorType | undefined,\n  queryArg: QueryArg,\n  meta: MetaType | undefined,\n  assertTagTypes: AssertTagTypes,\n): readonly FullTagDescription<string>[] {\n  const finalDescription = isFunction